const edition = globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2012,"grade":"7-8","contest":"Золотое руно","letters":"ABC","count":60,"language":"ru","points":3,"tasksFile":"7-8_1112_780.pdf","answersFile":"reviewed-7-8-v780.pdf","title":"Великобритания","sourceFile":"sources/golden-fleece/2012/interactive-7-8-v780.json","sections":[{"start":1,"title":"Общие сведения"},{"start":11,"title":"Литература"},{"start":21,"title":"Интересные факты"},{"start":31,"title":"История науки"},{"start":41,"title":"Архитектура"},{"start":51,"title":"Живопись"}],"variant":"780","editionSuffix":"v780","editionLabel":"Другие регионы","reviewedKey":true}, [{"number":1,"question":"День этого святого – национальный праздник Ирландии.","choices":["Эдуард","Патрик","Килиан"],"answer":1,"title":"Праздник Ирландии","steps":["В марте в Ирландии празднуют день покровителя страны, которому приписывают распространение христианства.","Речь о святом Патрике."]},{"number":2,"question":"Эта легендарная королева воевала с посягавшими на ее трон племянниками и стала прообразом героини одной из шекспировских пьес.","choices":["Боудикка","Корделия","Гвендолен"],"answer":1,"title":"Легенда о королеве","steps":["Король Лир разделил владения между дочерьми. Младшая осталась ему верна и стала королевой после его смерти в легенде, которую переработал Шекспир.","Её зовут Корделия."]},{"number":3,"question":"Этот документ был подписан при Иоанне Безземельном.","choices":["Билль о правах","Акт о Союзе","Великая хартия вольностей"],"answer":2,"title":"Хартия при Иоанне","steps":["В 1215 году восставшие бароны вынудили Иоанна принять ограничения своей власти. Соглашение закрепили письменно в Раннимиде.","Этот документ называют Великой хартией вольностей."]},{"number":4,"question":"Знаменитый провансальский трубадур Бертран де Борн наградил этого короля прозвищем «Да-и-Нет».","choices":["Альфред Великий","Ричард III","Ричард I Львиное Сердце"],"answer":2,"title":"Прозвище трубадура","steps":["Бертран де Борн был современником сыновей Генриха II Плантагенета и в стихах отзывался об их распрях.","Прозвище «Да-и-Нет» он употреблял для Ричарда Львиное Сердце."]},{"number":5,"question":"Во время какой войны произошла битва при Креси?","choices":["Столетней","Семилетней","Северной"],"answer":0,"title":"Битва при Креси","steps":["Сражение произошло во Франции в 1346 году. В нём английские лучники помогли армии Эдуарда III победить французское войско.","Англия и Франция воевали тогда в Столетней войне."]},{"number":6,"question":"Какая из названных правивших династий английская?","choices":["Каролинги","Габсбурги","Тюдоры"],"answer":2,"title":"Происхождение династии","steps":["После битвы при Босворте Англией стал править новый королевский дом. К нему принадлежали Генрих VIII и Елизавета I.","Эта династия — Тюдоры."]},{"number":7,"question":"В какой войне Великобритания и Россия были союзницами?","choices":["Северной","Крымской","Первой мировой"],"answer":2,"title":"Британия и Россия","steps":["В Крымской войне эти страны были противниками. К началу XX века они вошли в один блок вместе с Францией.","В Первой мировой войне Великобритания и Россия были союзницами."]},{"number":8,"question":"При каком британском монархе появилась и стала популярна песня «Боже, храни королеву/короля»?","choices":["Георг II","Виктория","Генрих VIII"],"answer":0,"title":"Песня о монархе","steps":["Самые ранние известные публичные исполнения «God Save the King» состоялись в лондонских театрах в 1745 году.","Тогда на британском престоле был Георг II."]},{"number":9,"question":"В битве при Ватерлоо британскими войсками командовал … .","choices":["Г. Нельсон","У. Черчилль","А. Веллингтон"],"answer":2,"title":"Командующий при Ватерлоо","steps":["В 1815 году союзные армии остановили Наполеона в Бельгии. Пруссаками командовал Блюхер, а британскими и частью союзных войск — другой полководец.","Его звали Артур Уэлсли, герцог Веллингтон."]},{"number":10,"question":"В Первую мировую войну Великобритания входила в военно-политический блок, который назывался … .","choices":["Антанта","Тройственный союз","Антигитлеровская коалиция"],"answer":0,"title":"Союз перед войной","steps":["До войны Британия заключила соглашения с Францией и Россией. Их государства противостояли Германии и союзникам Германии.","Этот блок известен как Антанта."]},{"number":11,"question":"Как называется литературное произведение Т. Мэлори, объединившее разрозненные легенды о короле Артуре?","choices":["«Принц Артур»","«Смерть Артура»","«Зеленый Рыцарь»"],"answer":1,"title":"Книга легенд","steps":["Томас Мэлори собрал рассказы об Артуре, Ланселоте и других рыцарях. В книге описывается и гибель артуровского королевства.","Сборник известен как «Смерть Артура»."]},{"number":12,"question":"Действие какой из трагедий У. Шекспира происходит в Британии?","choices":["«Гамлет»","«Макбет»","«Ромео и Джульетта»"],"answer":1,"title":"Место трагедии","steps":["В трагедии появляются шотландский король Дункан и военачальник, который захватывает его трон.","Шотландия находится на острове Великобритания. Пьеса называется «Макбет»."]},{"number":13,"question":"Фронтон театра «Глобус» украшало изречение римского поэта Петрония. В каком произведении У. Шекспира оно использовано?","choices":["«Как вам это понравится»","«Макбет»","«Двенадцатая ночь»"],"answer":0,"title":"Весь мир — сцена","steps":["Сравнение мира с театром стало девизом, который традиция связывает с шекспировским «Глобусом». В пьесе его произносит меланхоличный Жак.","Жак появляется в комедии «Как вам это понравится»."]},{"number":14,"question":"В каком романе В. Скотта историческим фоном является вражда между саксами и норманнами?","choices":["«Айвенго»","«Вудсток»","«Квентин Дорвард»"],"answer":0,"title":"Два народа в романе","steps":["Действие разворачивается после нормандского завоевания Англии. Отец героя, сакс Седрик, болезненно переживает власть норманнов.","Седрик — один из персонажей романа «Айвенго»."]},{"number":15,"question":"Какой английский писатель создал один из вариантов легенды о севильском аристократе?","choices":["Д. Дефо","П. Шелли","Дж. Байрон"],"answer":2,"title":"Севильский аристократ","steps":["В испанском предании аристократа-грешника зовут Дон Жуан. Английский поэт взял героя для сатирической поэмы.","Английский «Дон Жуан» принадлежит перу Байрона."]},{"number":16,"question":"Персонаж повести Дж. К. Джерома Поджер вбивал в стену гвоздь, чтобы повесить … .","choices":["картину","тарелку","часы"],"answer":0,"title":"Домашняя работа","steps":["Дядя Поджер берётся помочь всей семье. Поиск молотка и установка гвоздя превращаются в переполох.","Он пытается повесить на стену картину."]},{"number":17,"question":"Кто из героев романа Ч. Диккенса попадает в долговую тюрьму, отказавшись платить судебные издержки?","choices":["Пиквик","Уинкль","Снодграсс"],"answer":0,"title":"Путь в долговую тюрьму","steps":["Адвокаты добиваются денежного взыскания с героя после разбирательства о брачном обещании. Он отказывается платить из принципа.","В долговой тюрьме Флит оказывается мистер Пиквик."]},{"number":18,"question":"Кем приходились друг другу герои повести Р. Стивенсона доктор Джекил и мистер Хайд?","choices":["Это одно и то же лицо","Братьями","Отцом и сыном"],"answer":0,"title":"Тайна двух имён","steps":["Доктор принимает состав, который меняет его внешность и даёт проявиться скрытым желаниям.","Под именем мистера Хайда скрывается сам доктор Джекил."]},{"number":19,"question":"Пьеса какого английского драматурга легла в основу мюзикла «Моя прекрасная леди»?","choices":["Р. Шеридан","С. Беккет","Б. Шоу"],"answer":2,"title":"Из пьесы в мюзикл","steps":["Учёный учит цветочницу говорить на принятом в высшем обществе английском. В основу мюзикла легла пьеса «Пигмалион».","Пьесу написал Бернард Шоу."]},{"number":20,"question":"Кто был первым английским писателем, получившим Нобелевскую премию по литературе?","choices":["Б. Шоу","Р. Киплинг","Дж. Олдридж"],"answer":1,"title":"Литературная премия","steps":["Премию 1907 года дали за яркое повествовательное дарование и силу воображения автора «Книги джунглей».","Её получил Редьярд Киплинг."]},{"number":21,"question":"Кто из перечисленных поэтов похоронен в знаменитом «Уголке поэтов» Вестминстерского аббатства?","choices":["Дж. Чосер","У. Блейк","Дж. Китс"],"answer":0,"title":"Уголок поэтов","steps":["Первым знаменитым литератором, похороненным в этой части аббатства, стал автор «Кентерберийских рассказов».","Это Джефри Чосер."]},{"number":22,"question":"Согласно легенде, танцевавшая с королем знатная дама уронила подвязку. Окружающие засмеялись, а король поднял подвязку и повязал ее на свою ногу, положив начало ... .","choices":["танцу","рыцарскому ордену","моде на подвязки"],"answer":1,"title":"Подвязка и легенда","steps":["С подвязкой связывают девиз «Да будет стыдно тому, кто плохо об этом подумает». Он принадлежит учреждению Эдуарда III.","Это Орден Подвязки, то есть рыцарский орден."]},{"number":23,"question":"Считается, что этот драматург умер в день своего рождения.","choices":["У. Шекспир","К. Марло","Дж. Драйден"],"answer":0,"title":"Два события в апреле","steps":["Шекспира крестили 26 апреля 1564 года. По традиции днём рождения считают 23 апреля.","Шекспир умер 23 апреля 1616 года, поэтому традиционные даты совпадают."]},{"number":24,"question":"Дж. Кук начинал карьеру в Королевском военном флоте в должности … .","choices":["боцмана","штурмана","матроса"],"answer":2,"title":"Начало службы Кука","steps":["Кук уже умел управлять торговым судном, когда вступил в Королевский флот. Во флоте он начал службу с рядовой должности.","Он поступил матросом и позднее стал командиром."]},{"number":25,"question":"Что послужило причиной того, что после 2 сентября 1752 года в Англии сразу наступило 14-е?","choices":["Переход на григорианский календарь","Изменение вероисповедания","Требование Папы Римского"],"answer":0,"title":"Пропущенные даты","steps":["Старый календарь к XVIII веку расходился с новым на одиннадцать дней. При смене календаря разницу пришлось убрать.","Британия перешла на григорианский календарь, поэтому за 2 сентября последовало 14-е."]},{"number":26,"question":"Этот немецкий по происхождению композитор удостоен чести быть похороненным в Вестминстерском аббатстве.","choices":["И.С. Бах","Г.Ф. Гендель","Ф. Мендельсон"],"answer":1,"title":"Композитор в аббатстве","steps":["Композитор немецкого происхождения много лет работал в Лондоне. Здесь он написал ораторию «Мессия».","В Уголке поэтов похоронили Георга Фридриха Генделя."]},{"number":27,"question":"Кто из английских поэтов принимал активное участие в борьбе за независимость Греции?","choices":["П. Шелли","Дж. Байрон","Дж. Китс"],"answer":1,"title":"Борьба за независимость","steps":["Английский поэт поддержал борьбу греков против Османской империи. Он приехал в Месолонгион и там умер.","Поэтом был Джордж Байрон."]},{"number":28,"question":"Эту королеву называли «Бабушкой Европы».","choices":["Екатерина Арагонская","Виктория","Мария Тюдор"],"answer":1,"title":"Семейные связи","steps":["Дети и внуки этой королевы заключали браки с другими европейскими династиями. Её потомки заняли несколько тронов.","«Бабушкой Европы» прозвали Викторию."]},{"number":29,"question":"Произведение этого писателя о нападении инопланетян, транслируемое в эфире, вызвало панику у слушателей.","choices":["А. Кларк","А. Конан Дойл","Г. Уэллс"],"answer":2,"title":"Радиопостановка","steps":["В 1938 году радиотеатр подал вторжение марсиан в виде выпусков новостей. Некоторые слушатели приняли постановку за настоящий репортаж.","Радиопьесу сделали по «Войне миров» Герберта Уэллса. Масштабы паники поздние пересказы преувеличили."]},{"number":30,"question":"Одной из первых опубликованных книг этого писателя был учебник биологии.","choices":["К. Льюис","Г. Грин","Г. Уэллс"],"answer":2,"title":"Научный учебник","steps":["Автор «Машины времени» учился естественным наукам и преподавал. В начале карьеры он издал учебник по биологии.","Это Герберт Уэллс."]},{"number":31,"question":"Какой ученый участвовал в кругосветном путешествии, главными задачами которого были составление карт и проведение хронометрических измерений?","choices":["Ч. Дарвин","И. Ньютон","Д. Юм"],"answer":0,"title":"Плавание и наука","steps":["«Бигль» обследовал берега и выполнял картографические работы. Натуралист использовал экспедицию для наблюдений за растениями, животными и горными породами.","Натуралистом на корабле был Чарльз Дарвин."]},{"number":32,"question":"Кто из ученых был управляющим английского монетного двора?","choices":["Р. Бэкон","И. Ньютон","Дж. Максвелл"],"answer":1,"title":"Учёный и монеты","steps":["После научной работы в Кембридже этому физику поручили бороться с порчей монет и подделками. В 1699 году он возглавил Монетный двор.","Монетным двором управлял Исаак Ньютон."]},{"number":33,"question":"Этот ученый прославился как архитектор, но также был профессором математики и одним из основателей Лондонского королевского общества по развитию знаний о природе.","choices":["И. Джонс","У. Кент","К. Рен"],"answer":2,"title":"Архитектор и математик","steps":["Проектировщик собора Святого Павла преподавал астрономию и участвовал в первых встречах Королевского общества.","Речь о Кристофере Рене."]},{"number":34,"question":"Кому из этих знаменитых ученых приписывалось создание говорящей бронзовой головы?","choices":["Р. Бэкон","Дж. Холдейн","И. Ньютон"],"answer":0,"title":"Говорящая голова","steps":["В легендах об учёном XIII века его научные опыты приобрели волшебные черты. Один рассказ наделяет сделанную им бронзовую голову даром речи.","Эту легенду рассказывают о Роджере Бэконе."]},{"number":35,"question":"Этот предмет, изобретенный в XVIII веке английским придворным, используется в музыке, медицине и часовом деле.","choices":["Ланцет","Щипцы","Камертон"],"answer":2,"title":"Прибор для чистого тона","steps":["Металлическая вилка при ударе колеблется с известной частотой. По её звуку настраивают инструменты.","Этот прибор — камертон, появление которого связывают с придворным музыкантом Джоном Шором."]},{"number":36,"question":"В XIX веке в этой организации активно проводились исследования, способствовавшие введению всемирного времени.","choices":["Лондонское Королевское общество","Гринвичская обсерватория","Оксфордский университет"],"answer":1,"title":"Часы и меридиан","steps":["Наблюдения за светилами позволили привязать время к меридиану обсерватории. Международная конференция выбрала его начальным меридианом.","Речь о Гринвичской обсерватории."]},{"number":37,"question":"Считается, что этот шотландский ученый ввел понятие «лошадиная сила».","choices":["Дж. Уатт","А. Ампер","А. Вольт"],"answer":0,"title":"Измерение мощности","steps":["Чтобы показать выгоду паровой машины, инженер сравнивал её работу с работой тягловых лошадей.","Сравнительную единицу «лошадиная сила» ввёл в техническую практику Джеймс Уатт."]},{"number":38,"question":"Согласно модели этого ученого, строение атома подобно кондитерскому изделию.","choices":["И. Ньютон","Дж. Томсон","Э. Резерфорд"],"answer":1,"title":"Модель атома","steps":["В модели положительный заряд распределён по объёму, а электроны напоминают изюминки в тесте.","Так Джозеф Джон Томсон представлял атом до опытов Резерфорда."]},{"number":39,"question":"Единственный британец, дважды удостоенный Нобелевской премии, по профессии … .","choices":["биохимик","астрофизик","геолог"],"answer":0,"title":"Две премии","steps":["Фредерик Сенгер получил премии за установление строения инсулина и за работы по определению последовательности ДНК.","Обе работы относятся к биохимии."]},{"number":40,"question":"Этот ученый получил Нобелевскую премию за «открытие витаминов, стимулирующих процессы роста».","choices":["Э. Эдриан","Ф. Хопкинс","А. Флеминг"],"answer":1,"title":"Вещества в пище","steps":["Опыты показали, что одних белков, жиров, углеводов и минералов для роста недостаточно. Организму требуются дополнительные пищевые факторы.","Это открытие сделало известным Фредерика Хопкинса."]},{"number":41,"question":"В этом замке находится кукольный дом королевы Марии.","choices":["Эдинбургский","Дуврский","Виндзорский"],"answer":2,"title":"Кукольный дом","steps":["Эдвин Лаченс спроектировал миниатюрный дворец с обстановкой, водопроводом и библиотекой. Он предназначался королеве Марии, жене Георга V.","Дом выставлен в Виндзорском замке."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/41.webp","alt":"Кукольный дом · Иллюстрация к заданию 41","caption":"Иллюстрация к заданию 41","width":105,"height":59}},{"number":42,"question":"Это знаменитое аббатство, являющееся традиционным местом коронации британских монархов, находится в … .","choices":["Лондоне","Эдинбурге","Винчестере"],"answer":0,"title":"Аббатство коронаций","steps":["Вестминстерское аббатство находится недалеко от парламента и Темзы. В нём проводят коронации со времён Вильгельма Завоевателя.","Вестминстер — район Лондона."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/42.webp","alt":"Аббатство коронаций · Иллюстрация к заданию 42","caption":"Иллюстрация к заданию 42","width":105,"height":70}},{"number":43,"question":"В этом соборе похоронена писательница Дж. Остин.","choices":["Кентерберийский","Винчестерский","Солсберийский"],"answer":1,"title":"Могила писательницы","steps":["Писательница Джейн Остин умерла в Винчестере. Её могила находится в храме этого города.","Это Винчестерский собор в графстве Хэмпшир."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/43.webp","alt":"Могила писательницы · Иллюстрация к заданию 43","caption":"Иллюстрация к заданию 43","width":105,"height":58}},{"number":44,"question":"Этот дворец построен в XVI веке по приказу Генриха VIII.","choices":["Букингемский","Уайтхолл","Сент-Джеймсский"],"answer":2,"title":"Дворец XVI века","steps":["Кирпичный дворец с башнями и воротами начали строить при Генрихе VIII. Позднее с ним связали формальное название королевского двора.","Это Сент-Джеймсский дворец."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/44.webp","alt":"Дворец XVI века · Иллюстрация к заданию 44","caption":"Иллюстрация к заданию 44","width":105,"height":71}},{"number":45,"question":"В каком городе находится этот театр?","choices":["Стратфорд-на-Эйвоне","Лондон","Йорк"],"answer":1,"title":"Город «Глобуса»","steps":["Круглый театр под открытым небом напоминает сцену времён Шекспира. Современный «Глобус» построили у места, где стоял его предшественник.","Театр находится на берегу Темзы в Лондоне."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/45.webp","alt":"Город «Глобуса» · Иллюстрация к заданию 45","caption":"Иллюстрация к заданию 45","width":106,"height":69}},{"number":46,"question":"Знаменитый лондонский дворец, изображенный на этой фотографии, – это … .","choices":["музей восковых фигур","резиденция монархов","университет"],"answer":1,"title":"Назначение дворца","steps":["У фасада виден центральный балкон, с которого члены королевской семьи приветствуют публику. Это лондонский Букингемский дворец.","Он служит резиденцией монархов."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/46.webp","alt":"Назначение дворца · Иллюстрация к заданию 46","caption":"Иллюстрация к заданию 46","width":87,"height":66}},{"number":47,"question":"В этом здании находится один из самых известных в мире музеев – музей … .","choices":["восковых фигур","театральных декораций","декоративно-прикладного искусства"],"answer":2,"title":"Музей прикладных искусств","steps":["В музее Виктории и Альберта выставляют одежду, керамику, мебель и другие произведения, рассчитанные на практическое использование.","Музей посвящён декоративно-прикладному искусству и дизайну."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/47.webp","alt":"Музей прикладных искусств · Иллюстрация к заданию 47","caption":"Иллюстрация к заданию 47","width":87,"height":64}},{"number":48,"question":"Где в Лондоне находится этот архитектурный памятник в китайском стиле?","choices":["Гайд-парк","Риджентс-парк","Сады Кью"],"answer":2,"title":"Пагода в саду","steps":["Высокая многоярусная башня, вдохновлённая архитектурой Китая, построена по проекту Уильяма Чемберса.","Большая пагода расположена в лондонских садах Кью."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/48.webp","alt":"Пагода в саду · Иллюстрация к заданию 48","caption":"Иллюстрация к заданию 48","width":88,"height":59}},{"number":49,"question":"Это родовое поместье недалеко от Йорка считается одним из самых ярких памятников архитектуры барокко в Великобритании.","choices":["Замок Бленхейм","Замок Ховард","Бергли-Хаус"],"answer":1,"title":"Барокко в Йоркшире","steps":["Дворец с куполом и длинными крыльями спроектировал Джон Ванбру при участии Николаса Хоксмура.","Этот ансамбль называется замком Ховард."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/49.webp","alt":"Барокко в Йоркшире · Иллюстрация к заданию 49","caption":"Иллюстрация к заданию 49","width":88,"height":66}},{"number":50,"question":"Это сооружение называется … .","choices":["Королевский Альберт-холл","Музей Виктории и Альберта","Мемориал принца Альберта"],"answer":0,"title":"Концертный зал","steps":["Круглое здание из красного кирпича украшает пояс с аллегориями искусств. Его строительство связано с памятью о принце Альберте.","Это концертный зал Королевский Альберт-холл."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/50.webp","alt":"Концертный зал · Иллюстрация к заданию 50","caption":"Иллюстрация к заданию 50","width":87,"height":57}},{"number":51,"question":"Про пейзажи этого художника Стендаль написал, что их правдивость поражает и увлекает.","choices":["Р. Бонингтон","У. Тернер","Дж. Констебл"],"answer":2,"title":"Правдивость пейзажа","steps":["В пейзажах английского художника облака, деревья и сельские работы занимают важное место. Его выставка во Франции повлияла на местных живописцев.","Речь о Джоне Констебле, авторе «Телеги для сена»."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/51.webp","alt":"Правдивость пейзажа · Иллюстрация к заданию 51","caption":"Иллюстрация к заданию 51","width":86,"height":70}},{"number":52,"question":"Кто из европейских художников запечатлел казненного во время английской революции короля?","choices":["А. Ван Дейк","П. Рубенс","Г. Гольбейн мл."],"answer":0,"title":"Портрет Карла I","steps":["При дворе Карла I работал фламандский художник. Он писал короля верхом на коне и в охотничьем костюме.","Карла I запечатлел Антонис Ван Дейк."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/52.webp","alt":"Портрет Карла I · Иллюстрация к заданию 52","caption":"Иллюстрация к заданию 52","width":171,"height":144}},{"number":53,"question":"Этот английский художник в 1768 г. стал первым президентом Королевской Академии художеств.","choices":["Дж. Рейнолдс","Т. Гейнсборо","У. Хогарт"],"answer":0,"title":"Создание Академии","steps":["Королевская академия художеств была основана при Георге III. Её первым президентом избрали признанного портретиста.","Эту должность занял Джошуа Рейнолдс."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/53.webp","alt":"Создание Академии · Иллюстрация к заданию 53","caption":"Иллюстрация к заданию 53","width":150,"height":173}},{"number":54,"question":"Имя какого итальянского живописца эпохи Возрождения использовали в названии своего объединения английские художники?","choices":["Микеланджело","Рафаэль","Тициан"],"answer":1,"title":"Название братства","steps":["Английские художники восхищались искусством до эпохи Высокого Возрождения. Поэтому в названии указали период «до Рафаэля».","Своё объединение они назвали Братством прерафаэлитов."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/54.webp","alt":"Название братства · Иллюстрация к заданию 54","caption":"Иллюстрация к заданию 54","width":76,"height":86}},{"number":55,"question":"Портреты этой известной женщины Великобритании создали Дж. Рейнолдс и Т. Гейнсборо.","choices":["Королева Шарлотта","Герцогиня де Бофор","Актриса Сара Сиддонс"],"answer":2,"title":"Два портрета актрисы","steps":["Рейнолдс представил женщину как трагическую музу, а Гейнсборо изобразил её в полосатом платье и шляпе.","В обоих случаях позировала актриса Сара Сиддонс."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/55.webp","alt":"Два портрета актрисы · Иллюстрация к заданию 55","caption":"Иллюстрация к заданию 55","width":149,"height":190}},{"number":56,"question":"Картина «Девушка с креветками» принадлежит кисти этого художника.","choices":["Дж. Уистлер","У. Блейк","У. Хогарт"],"answer":2,"title":"Продавщица креветок","steps":["Художник быстро написал улыбчивую продавщицу, которая несёт на голове корзину. Картина отличается свободными мазками.","Эту работу создал Уильям Хогарт."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/56.webp","alt":"Продавщица креветок · Иллюстрация к заданию 56","caption":"Иллюстрация к заданию 56","width":148,"height":189}},{"number":57,"question":"Этот художник известен портретами офицеров – участников войны 1812 года.","choices":["Дж. Миллес","Т. Гейнсборо","Дж. Доу"],"answer":2,"title":"Галерея офицеров","steps":["Для Военной галереи Зимнего дворца британский художник писал портреты участников войны с Наполеоном.","Работу выполнил Джордж Доу при участии помощников."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/57.webp","alt":"Галерея офицеров · Иллюстрация к заданию 57","caption":"Иллюстрация к заданию 57","width":152,"height":169}},{"number":58,"question":"Кто автор этой картины, на которой изображен мчащийся поезд?","choices":["Дж. Уистлер","Дж. Миллес","У. Тернер"],"answer":2,"title":"Поезд в дождь","steps":["На полотне паровоз мчится через дождь и туман. Пейзаж почти растворяется в свете и влажном воздухе.","«Дождь, пар и скорость» написал Уильям Тёрнер."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/58.webp","alt":"Поезд в дождь · Иллюстрация к заданию 58","caption":"Иллюстрация к заданию 58","width":93,"height":69}},{"number":59,"question":"Кто из британских художников писал стихи и сам их иллюстрировал?","choices":["У. Блейк","У. Хогарт","Т. Гейнсборо"],"answer":0,"title":"Стихи и картинки","steps":["Автор «Песен Невинности и Опыта» соединял стихи с авторскими рисунками на гравированных листах.","Он подписывал книги именем Уильяма Блейка."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/59.webp","alt":"Стихи и картинки · Иллюстрация к заданию 59","caption":"Иллюстрация к заданию 59","width":190,"height":132}},{"number":60,"question":"Кто из художников прославился картиной, написанной по знаменитой пьесе «Опера нищих»?","choices":["У. Блейк","У. Хогарт","Дж. Рейнолдс"],"answer":1,"title":"Опера на холсте","steps":["В сатирической пьесе Джона Гея герои предстают в роли нищих и преступников. Английский живописец написал сцену из спектакля.","«Оперу нищих» изобразил Уильям Хогарт."],"figure":{"src":"assets/golden-fleece/2012/interactive-7-8-780/60.webp","alt":"Опера на холсте · Иллюстрация к заданию 60","caption":"Иллюстрация к заданию 60","width":170,"height":131}}]);
